---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Action log: Every read, search, edit and command, logged as it runs.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change action-log.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './action-log.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="action-log" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="alg panel">
  <div class="alg-h"><span class="alg-t">Agent activity</span><span class="alg-st"><span class="spin"></span><span class="alg-sum">Running</span></span></div>
  <ol class="alg-list"></ol>
</div>
  </Fragment></div>
</div>
<script>
  import './action-log.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Action log ---------- */
.alg{padding:var(--dm-s-2)}
.alg-h{display:flex;align-items:center;justify-content:space-between;padding:var(--dm-s-2) 10px 6px}
.alg-t{font-weight:500}
.alg-st{display:inline-flex;align-items:center;gap:7px;font-size:12.5px;color:var(--dm-fg2)}
.alg-st .spin{width:10px;height:10px}
.alg-list{list-style:none;margin:0;padding:0}
/* on a card the log keeps the room its five steps fill, so the header doesn't climb as each one lands */
.stage-in>.alg{min-height:326px}
.alg-it{border-radius:var(--dm-r-in);transition:background .25s}
@media (hover:hover) and (pointer:fine){.alg-it:hover{background:var(--dm-row)}}
.alg-row{display:flex;align-items:center;gap:10px;width:100%;padding:var(--dm-s-2) 10px;text-align:left}
.alg-ic{width:26px;height:26px;border-radius:var(--dm-r-sm);background:var(--dm-chip);display:grid;place-items:center;color:var(--dm-fg2);flex:none;transition:background .25s}
@media (hover:hover) and (pointer:fine){.alg-it:hover .alg-ic{background:var(--dm-surface)}}
.alg-tx{flex:1;min-width:0}
.alg-tx b{font-weight:500}
.alg-tx code{font-family:var(--dm-mono);font-size:12px}
.alg-tx .d{display:block;font-size:12px;color:var(--dm-muted)}
.alg-r{display:flex;align-items:center;gap:var(--dm-s-2);color:var(--dm-muted);font-size:12px}
.alg-r .g{width:14px;display:grid;place-items:center}
.alg-det{margin:0 10px 0 46px}
.alg-det pre{margin:0 0 10px;font-family:var(--dm-mono);font-size:11.5px;line-height:1.6;background:var(--dm-surface);border-radius:calc(10px * var(--dm-rk));padding:var(--dm-s-2) 10px;white-space:pre-wrap;color:var(--dm-fg2);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
.alg-det .a{color:var(--dm-add)}.alg-det .x{color:var(--dm-del)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, DM, I, enter, html, swap } from '../core/core.js';
DM.def('action-log', (r, c) => {
  const list = $('.alg-list', r);
  const acts = [
    { ic:'file-text', t:'Read <code>Pricing.tsx</code>', d:'src/pages, 212 lines', ms:'0.4s', det:'export function Pricing() {\n  return &lt;Grid cols={3} gap={20}&gt;…' },
    { ic:'search', t:'Searched Figma for <code>Button</code>', d:'6 matches in Components.fig', ms:'1.1s', det:'Button / Primary\nButton / Secondary\nButton / Ghost  +3' },
    { ic:'edit', t:'Edited <code>PricingCard.tsx</code>', d:'<span style="color:var(--dm-add)">+18</span> <span style="color:var(--dm-del)">−7</span> lines', ms:'2.3s', det:'<span class="x">− gap: 20px;</span>\n<span class="a">+ gap: var(--space-6);</span>' },
    { ic:'term', t:'Ran <code>npm test</code>', d:'24 tests passed', ms:'3.2s', det:'✓ PricingCard renders 3 plans\n✓ toggles yearly billing\n24 passed, 0 failed' },
    { ic:'pr', t:'Opened a pull request', d:'#412, Use shared spacing tokens', ms:'0.6s', det:'feat/pricing-spacing → main\n3 commits, ready for review' }
  ];
  const sum = $('.alg-sum', r), st = $('.alg-st', r);
  c.run(async () => {
    let total = 0;
    for (const a of acts){
      const li = html(`<li class="alg-it"><button class="alg-row" aria-expanded="false"><span class="alg-ic">${I(a.ic)}</span><span class="alg-tx"><b>${a.t}</b><span class="d">${a.d}</span></span><span class="alg-r"><span class="num ms"></span><span class="g"><span class="spin" style="width:10px;height:10px"></span></span></span></button><div class="fold shut alg-det"><div><pre>${a.det}</pre></div></div></li>`);
      list.appendChild(li); enter(li);
      const btn = $('.alg-row', li), det = $('.alg-det', li);
      btn.onclick = () => { const s = det.classList.toggle('shut'); btn.setAttribute('aria-expanded', !s); };
      swap(sum, 'Running step ' + list.children.length);
      await c.wait(950);
      $('.g', li).innerHTML = `<span style="color:var(--dm-ok)">${I('check','xs')}</span>`; enter($('.g', li).firstElementChild);
      $('.ms', li).textContent = a.ms; total += parseFloat(a.ms);
    }
    st.innerHTML = `<span class="dot" style="color:var(--dm-ok)"></span><span>5 steps, ${total.toFixed(1)}s</span>`; enter(st);
  });
});
